// Renascor site script.
// Loads data.json (generated by scripts/build_site.py) and renders the
// catalogue as cards or as a table, with search and filter controls.

(function () {
  'use strict';

  var VIEW_KEY = 'renascor-view';

  let entries = [];
  let filtered = [];
  let view = 'cards';

  const els = {
    search: document.getElementById('search'),
    language: document.getElementById('f-language'),
    encoding: document.getElementById('f-encoding'),
    status: document.getElementById('f-status'),
    period: document.getElementById('f-period'),
    region: document.getElementById('f-region'),
    stats: document.getElementById('stats'),
    heroStats: document.getElementById('hero-stats'),
    cards: document.getElementById('cards'),
    tbody: document.getElementById('tbody'),
    viewCards: document.getElementById('view-cards'),
    viewTable: document.getElementById('view-table'),
    dlCsv: document.getElementById('dl-csv'),
    dlJson: document.getElementById('dl-json'),
  };

  const numberFmt = new Intl.NumberFormat();

  function load() {
    fetch('data.json')
      .then(r => r.json())
      .then(data => {
        entries = data.entries || [];
        filtered = entries.slice();
        restoreView();
        populateFilters();
        renderHero();
        render();
      })
      .catch(err => {
        els.stats.textContent = 'Failed to load data: ' + err.message;
      });
  }

  function restoreView() {
    try {
      const saved = localStorage.getItem(VIEW_KEY);
      if (saved === 'cards' || saved === 'table') view = saved;
    } catch (e) { /* private browsing: keep the default */ }
  }

  function saveView() {
    try { localStorage.setItem(VIEW_KEY, view); } catch (e) { /* ignore */ }
  }

  function setView(next) {
    if (view === next) return;
    view = next;
    saveView();
    applyView();
  }

  function applyView() {
    document.body.classList.toggle('view-card', view === 'cards');
    document.body.classList.toggle('view-table', view === 'table');
    els.viewCards.setAttribute('aria-pressed', String(view === 'cards'));
    els.viewTable.setAttribute('aria-pressed', String(view === 'table'));
  }

  function renderHero() {
    if (!els.heroStats) return;
    const totalWords = entries.reduce((s, e) =>
      s + (typeof e.words === 'number' ? e.words : 0), 0);
    const totalTexts = entries.reduce((s, e) =>
      s + (typeof e.texts === 'number' ? e.texts : 0), 0);
    const langs = new Set();
    entries.forEach(e => (e.languages || []).forEach(l => langs.add(l)));
    const stat = (value, label) => {
      const div = document.createElement('div');
      const b = document.createElement('b');
      b.textContent = numberFmt.format(value);
      div.appendChild(b);
      div.appendChild(document.createTextNode(' ' + label));
      return div;
    };
    els.heroStats.appendChild(stat(entries.length, 'editions'));
    els.heroStats.appendChild(stat(langs.size, 'languages'));
    if (totalTexts) els.heroStats.appendChild(stat(totalTexts, 'texts'));
    if (totalWords) els.heroStats.appendChild(stat(Math.round(totalWords / 1e8) / 10, 'Bn words'));
  }

  function populateFilters() {
    const languages = new Set();
    const encodings = new Set();
    const statuses = new Set();
    const periods = new Set();
    const regions = new Set();
    entries.forEach(e => {
      (e.languages || []).forEach(l => languages.add(l));
      if (e.encoding) encodings.add(e.encoding);
      if (e.status) statuses.add(e.status);
      if (e.period) periods.add(e.period);
      if (e.region) regions.add(e.region);
    });
    fillSelect(els.language, [...languages].sort());
    fillSelect(els.encoding, [...encodings].sort());
    fillSelect(els.status, [...statuses].sort());
    fillSelect(els.period, [...periods].sort());
    fillSelect(els.region, [...regions].sort());
  }

  function fillSelect(select, values) {
    values.forEach(v => {
      const opt = document.createElement('option');
      opt.value = v;
      opt.textContent = v;
      select.appendChild(opt);
    });
  }

  function applyFilters() {
    const q = els.search.value.toLowerCase().trim();
    const lang = els.language.value;
    const enc = els.encoding.value;
    const stat = els.status.value;
    const per = els.period.value;
    const reg = els.region.value;

    filtered = entries.filter(e => {
      if (lang && !(e.languages || []).includes(lang)) return false;
      if (enc && e.encoding !== enc) return false;
      if (stat && e.status !== stat) return false;
      if (per && e.period !== per) return false;
      if (reg && e.region !== reg) return false;
      if (q) {
        const hay = [
          e.title, e.institution, e.author, e.notes,
          (e.languages || []).join(' '),
          e.region, e.period,
        ].filter(Boolean).join(' ').toLowerCase();
        if (!hay.includes(q)) return false;
      }
      return true;
    });
    render();
  }

  function yearsActive(e) {
    const ya = e.years_active;
    if (!ya) return '';
    return ya.end === 'ongoing' ? ya.start + '–ongoing' : ya.start + (ya.end ? '–' + ya.end : '–');
  }

  function words(e) {
    return typeof e.words === 'number' ? numberFmt.format(e.words) : '';
  }

  function render() {
    els.stats.textContent = filtered.length + ' of ' + entries.length + ' entries';
    els.cards.innerHTML = '';
    els.tbody.innerHTML = '';
    filtered.forEach(e => els.cards.appendChild(card(e)));
    filtered.forEach(e => els.tbody.appendChild(row(e)));
  }

  function card(e) {
    const div = document.createElement('article');
    div.className = 'card';

    const head = document.createElement('div');
    head.className = 'card-head';
    const h = document.createElement('h2');
    h.innerHTML = '<a href="' + escapeHtml(e.url) + '" target="_blank" rel="noopener">' +
      escapeHtml(e.title) + '</a>';
    head.appendChild(h);
    head.appendChild(badge(e.status));
    div.appendChild(head);
    if (e.institution) {
      const inst = document.createElement('p');
      inst.className = 'card-inst';
      inst.textContent = e.institution;
      div.appendChild(inst);
    }

    const meta = document.createElement('div');
    meta.className = 'meta';
    (e.languages || []).forEach(l => meta.appendChild(tag(l)));
    if (e.encoding) meta.appendChild(tag(e.encoding.toUpperCase(), 'label'));
    if (e.period) meta.appendChild(tag(e.period, 'label'));
    if (e.region) meta.appendChild(tag(e.region, 'label'));
    if (typeof e.words === 'number') meta.appendChild(tag(numberFmt.format(e.words) + ' words', 'label'));
    if (typeof e.texts === 'number') meta.appendChild(tag(numberFmt.format(e.texts) + ' texts', 'label'));
    const ya = yearsActive(e);
    if (ya) meta.appendChild(tag(ya, 'label'));
    div.appendChild(meta);

    if (e.author || e.date) {
      const line = document.createElement('p');
      line.className = 'meta-line';
      line.innerHTML = (e.author ? '<span><b>Author:</b> ' + escapeHtml(e.author) + '</span>' : '') +
        (e.date ? '<span><b>Source date:</b> ' + escapeHtml(e.date) + '</span>' : '');
      div.appendChild(line);
    }

    if (e.notes) {
      const notes = document.createElement('p');
      notes.className = 'card-notes';
      notes.textContent = e.notes;
      if (e.notes.length > 260) {
        notes.classList.remove('expanded');
        const more = document.createElement('button');
        more.type = 'button';
        more.className = 'more';
        more.textContent = 'Read more';
        more.addEventListener('click', () => {
          const open = notes.classList.toggle('expanded');
          more.textContent = open ? 'Show less' : 'Read more';
        });
        const notesWrap = document.createDocumentFragment();
        notesWrap.appendChild(notes);
        notesWrap.appendChild(more);
        div.appendChild(notesWrap);
      } else {
        div.appendChild(notes);
      }
    }

    const foot = document.createElement('div');
    foot.className = 'card-foot';
    foot.innerHTML = '<span>' + (e.provenance === 'discovered' ? 'Discovered by automated search' : 'Submitted') +
      ' · ' + escapeHtml(e.date_added || '') +
      (e.last_modified ? ' · updated ' + escapeHtml(e.last_modified) : '') + '</span>' +
      '<a class="visit" href="' + escapeHtml(e.url) + '" target="_blank" rel="noopener">Visit edition →</a>';
    div.appendChild(foot);
    return div;
  }

  function tag(text, cls) {
    const t = document.createElement('span');
    t.className = 'tag' + (cls ? ' ' + cls : '');
    t.textContent = text;
    return t;
  }

  function badge(status) {
    const s = document.createElement('span');
    s.className = 'badge ' + (status || '');
    s.textContent = status || '';
    return s;
  }

  function row(e) {
    const tr = document.createElement('tr');
    tr.innerHTML =
      '<td><a href="' + escapeHtml(e.url) + '" target="_blank" rel="noopener">' +
      escapeHtml(e.title) + '</a></td>' +
      '<td>' + escapeHtml((e.languages || []).join(', ')) + '</td>' +
      '<td>' + escapeHtml(e.period || '') + '</td>' +
      '<td>' + escapeHtml(e.region || '') + '</td>' +
      '<td>' + escapeHtml(e.encoding || '') + '</td>' +
      '<td class="num">' + words(e) + '</td>' +
      '<td>' + escapeHtml(yearsActive(e)) + '</td>' +
      '<td>' + escapeHtml(e.institution || '') + '</td>' +
      '<td>' + badgeHtml(e.status) + '</td>';
    return tr;
  }

  function badgeHtml(status) {
    const s = document.createElement('span');
    s.className = 'badge ' + (status || '');
    s.textContent = status || '';
    return s.outerHTML;
  }

  function escapeHtml(s) {
    if (!s) return '';
    return String(s)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  function downloadCsv() {
    const cols = ['title', 'url', 'languages', 'encoding', 'status', 'institution',
                  'period', 'words', 'region', 'author', 'date', 'years_active', 'provenance', 'date_added'];
    const lines = [cols.join(',')];
    filtered.forEach(e => {
      lines.push(cols.map(c => csvCell(e[c])).join(','));
    });
    const blob = new Blob([lines.join('\n')], { type: 'text/csv' });
    saveBlob(blob, 'renascor.csv');
  }

  function csvCell(v) {
    if (v === null || v === undefined) return '';
    if (Array.isArray(v)) v = v.join('; ');
    if (typeof v === 'object') v = JSON.stringify(v);
    v = String(v);
    if (/[",\n]/.test(v)) return '"' + v.replace(/"/g, '""') + '"';
    return v;
  }

  function downloadJson() {
    const blob = new Blob([JSON.stringify(filtered, null, 2)], { type: 'application/json' });
    saveBlob(blob, 'renascor.json');
  }

  function saveBlob(blob, name) {
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = name;
    a.click();
    URL.revokeObjectURL(a.href);
  }

  els.search.addEventListener('input', applyFilters);
  els.language.addEventListener('change', applyFilters);
  els.encoding.addEventListener('change', applyFilters);
  els.status.addEventListener('change', applyFilters);
  els.period.addEventListener('change', applyFilters);
  els.region.addEventListener('change', applyFilters);
  els.viewCards.addEventListener('click', () => setView('cards'));
  els.viewTable.addEventListener('click', () => setView('table'));
  els.dlCsv.addEventListener('click', downloadCsv);
  els.dlJson.addEventListener('click', downloadJson);

  load();
})();